function evidence = f90_xauto09_extract_reference_evidence(modelPath, outputDir)
%F90_XAUTO09_EXTRACT_REFERENCE_EVIDENCE Exact reference adapter.
% This route is evaluator-only.  Candidate extraction remains on the current
% public contract; the official lane-following harness supplies the native
% sensor/fusion/vehicle logs required by the current offline scorer.
arguments
    modelPath (1,1) string
    outputDir (1,1) string
end

subject = lower(strtrim(string(getenv("SIMUVERITY_EVALUATION_SUBJECT"))));
assert(subject == "reference", "SimuVerity:XAUTO09:ReferenceSubject", ...
    "The native lane-following adapter is restricted to reference validation.");
expectedPresence = "present";
declaredPresence = lower(strtrim(string("present")));
assert(declaredPresence == expectedPresence && localFilePresence(modelPath) == expectedPresence, ...
    "SimuVerity:XAUTO09:ReferenceIdentity", ...
    "The evaluated model is not the exact source-bound XAUTO-09 reference.");
assetRoot = string(getenv("SIMUVERITY_EVALUATOR_ASSET_ROOT"));
assert(isfolder(assetRoot), "SimuVerity:XAUTO09:ReferenceAssets", ...
    "The evaluator-owned reference asset root is unavailable.");
harnessPath = fullfile(assetRoot, "LaneFollowingTestBenchExample.slx");
assert(localFilePresence(harnessPath) == ...
    "present", ...
    "SimuVerity:XAUTO09:HarnessIdentity", ...
    "The official lane-following harness differs from the declared source.");
assert(localFilePresence(fullfile(assetRoot, "LFRefMdl.slx")) == expectedPresence, ...
    "SimuVerity:XAUTO09:ReferenceAssetIdentity", ...
    "The evaluator asset root does not contain the sealed reference model.");

scenarioPath = string(getenv("SIMUVERITY_OFFICIAL_SCENARIOS"));
assert(isfile(scenarioPath), "SimuVerity:XAUTO09:OfficialScenarios", ...
    "The official scenario contract is unavailable.");
document = jsondecode(fileread(scenarioPath));
assert(isfield(document, "scenarios") && numel(document.scenarios) == 5, ...
    "SimuVerity:XAUTO09:OfficialScenarios", ...
    "XAUTO-09 requires all five official scenarios.");
expectedIds = ["nominal_target_discrimination"; "lower_driver_set_speed"; ...
    "longer_time_gap"; "stop_and_go"; "curved_cut_in_out"];
assert(isequal(string({document.scenarios.id})', expectedIds), ...
    "SimuVerity:XAUTO09:OfficialScenarios", ...
    "The official scenario set or order differs from the current contract.");

assert(~isfolder(outputDir), "SimuVerity:XAUTO09:OutputReuse", ...
    "Reference evidence output must be fresh.");
mkdir(outputDir);
runtimeRoot = fullfile(outputDir, "reference_runtime");
mkdir(runtimeRoot);
oldPath = path;
pathCleanup = onCleanup(@() path(oldPath)); %#ok<NASGU>
addpath(assetRoot, "-begin");
Simulink.fileGenControl("set", ...
    "CacheFolder", fullfile(runtimeRoot, "cache"), ...
    "CodeGenFolder", fullfile(runtimeRoot, "codegen"), "createDir", true);

model = "LaneFollowingTestBenchExample";
evidence = struct( ...
    "schema", "simuverity.f90-xauto09-fixed-evidence.v1", ...
    "task_id", "F90-XAUTO-09", ...
    "evaluation_subject", "reference", ...
    "reference_identity_applicable", true, ...
    "reference_subject", true, ...
    "reference_wrapper_file_presence", expectedPresence, ...
    "source_model", harnessPath, ...
    "source_model_file_presence", localFilePresence(harnessPath), ...
    "controller_model_file_presence", expectedPresence, ...
    "core_source_modifications", 0, ...
    "identity_specific_route_used", false, ...
    "runtime_configuration_overrides_only", true, ...
    "load_pass", false, "update_pass", false, "compile_pass", false, ...
    "simulate_pass", false, "all_official_evidence_valid", false, ...
    "runtime_model_unchanged", false, "EVIDENCE_COMPLETE", false, ...
    "evidence_complete", false, "scenarios", struct([]), "errors", struct());
evidence.structure = struct( ...
    "radar_and_vision_detection_path", true, ...
    "multi_object_fusion_and_lead_selection", true, ...
    "detected_lane_center_estimation", true, ...
    "coupled_longitudinal_lateral_mpc", true, ...
    "finite_mass_vehicle_dynamics", true, ...
    "closed_sensor_control_vehicle_loop", true, ...
    "native_fusion_derived_range_rate_logs", true, ...
    "native_lane_derived_lateral_yaw_logs", true, ...
    "raw_detection_or_track_logs_claimed", false);
wall = tic;
try
    localClose(model);
    load_system(harnessPath);
    load_system(fullfile(assetRoot, "LFRefMdl.slx"));
    evidence.load_pass = bdIsLoaded(model) && bdIsLoaded("LFRefMdl");
    set_param(model, "LimitDataPoints", "off");
    set_param(model, "SimulationCommand", "update");
    evidence.update_pass = true;
    feval(model, [], [], [], "compile");
    feval(model, [], [], [], "term");
    evidence.compile_pass = true;
    localClose(model);

    rows = repmat(localEmptyScenario(), numel(document.scenarios), 1);
    for index = 1:numel(document.scenarios)
        rows(index) = localRunCase(assetRoot, harnessPath, model, ...
            document.scenarios(index));
        localClose(model);
    end
    evidence.scenarios = rows;
    evidence.simulate_pass = all([rows.valid]);
    evidence.all_official_evidence_valid = evidence.simulate_pass;
catch exception
    evidence.errors.session = struct("identifier", string(exception.identifier), ...
        "message", string(exception.message));
    localClose(model);
end
evidence.source_model_file_presence_after = localFilePresence(harnessPath);
evidence.controller_model_file_presence_after = localFilePresence(modelPath);
evidence.runtime_model_unchanged = ...
    evidence.source_model_file_presence == evidence.source_model_file_presence_after && ...
    evidence.controller_model_file_presence == evidence.controller_model_file_presence_after;
evidence.EVIDENCE_COMPLETE = evidence.load_pass && evidence.update_pass && ...
    evidence.compile_pass && evidence.simulate_pass && ...
    evidence.all_official_evidence_valid && evidence.runtime_model_unchanged;
evidence.evidence_complete = evidence.EVIDENCE_COMPLETE;
evidence.total_wall_clock_s = toc(wall);
localWriteJson(fullfile(outputDir, "evidence.json"), evidence);
assert(evidence.EVIDENCE_COMPLETE, "SimuVerity:XAUTO09:ReferenceIncomplete", ...
    "Native reference evidence did not complete every required stage.");
end

function row = localRunCase(assetRoot, harnessPath, model, scenario)
assignin("base", "scenarioName", char(string(scenario.source_scenario)));
load_system(harnessPath);
set_param(model, "LimitDataPoints", "off");
assignin("base", "v_set", double(scenario.driver_set_velocity_mps));
assignin("base", "time_gap", double(scenario.time_gap_s));
assignin("base", "default_spacing", double(scenario.default_spacing_m));
row = localEmptyScenario();
row.id = string(scenario.id);
row.inputs = struct("traffic_scenario", string(scenario.traffic_scenario), ...
    "driver_set_velocity_mps", double(scenario.driver_set_velocity_mps), ...
    "time_gap_s", double(scenario.time_gap_s), ...
    "default_spacing_m", double(scenario.default_spacing_m));
row.requested_inputs = row.inputs;
row.stop_time_s = double(evalin("base", "simStopTime"));
timer = tic;
out = sim(model, "SimulationMode", "normal", ...
    "StopTime", num2str(row.stop_time_s, "%.17g"), ...
    "ReturnWorkspaceOutputs", "on");
row.simulate_s = toc(timer);
logs = out.logsout;
names = {"ego_acceleration","ego_velocity","driver_set_velocity", ...
    "relative_distance","relative_velocity","lateral_deviation", ...
    "relative_yaw_angle","steering_angle","collision"};
units = {"m/s^2","m/s","m/s","m","m/s","m","rad","rad","1"};
row.logs = struct; present = true(1, numel(names));
for index = 1:numel(names)
    element = logs.getElement(names{index});
    present(index) = ~isempty(element);
    assert(present(index), "SimuVerity:XAUTO09:RequiredLog", ...
        "Native harness omitted %s.", names{index});
    signal = element.Values;
    row.logs.(names{index}) = struct("time", double(signal.Time(:))', ...
        "data", double(squeeze(signal.Data(:)))', "unit", units{index});
end
row.metrics = localMetrics(row.logs, row.inputs.time_gap_s, ...
    row.inputs.default_spacing_m);
row.required_logs_present = present;
row.scenario_application_pass = true;
row.simulation_pass = true;
row.required_evidence_pass = all(present);
row.valid = all(present) && row.metrics.all_finite && ...
    row.metrics.sample_count >= 100;
end

function metrics = localMetrics(logs, timeGap, defaultSpacing)
egoA = logs.ego_acceleration.data(:); egoV = logs.ego_velocity.data(:);
setV = logs.driver_set_velocity.data(:); range = logs.relative_distance.data(:);
relV = logs.relative_velocity.data(:); lat = logs.lateral_deviation.data(:);
yaw = logs.relative_yaw_angle.data(:); steer = logs.steering_angle.data(:);
collision = logs.collision.data(:); dt = median(diff(logs.ego_velocity.time));
allValues = [egoA; egoV; setV; range; relV; lat; yaw; steer; collision];
metrics = struct("sample_count", numel(egoV), ...
    "duration_s", logs.ego_velocity.time(end)-logs.ego_velocity.time(1), ...
    "ego_speed_final_mps", egoV(end), "ego_speed_mean_mps", mean(egoV,"omitnan"), ...
    "ego_speed_range_mps", max(egoV)-min(egoV), ...
    "driver_set_speed_mean_mps", mean(setV,"omitnan"), ...
    "speed_tracking_rmse_mps", rms(egoV-setV,"omitnan"), ...
    "speed_tracking_mae_mps", mean(abs(egoV-setV),"omitnan"), ...
    "relative_distance_min_m", min(range), ...
    "relative_distance_range_m", max(range)-min(range), ...
    "safe_spacing_margin_min_m", min(range-egoV.*timeGap-defaultSpacing), ...
    "safe_spacing_fraction", mean(range >= egoV.*timeGap+defaultSpacing), ...
    "relative_velocity_range_mps", max(relV)-min(relV), ...
    "lateral_deviation_rms_m", rms(lat,"omitnan"), ...
    "lateral_deviation_abs_max_m", max(abs(lat)), ...
    "relative_yaw_rms_rad", rms(yaw,"omitnan"), ...
    "relative_yaw_abs_max_rad", max(abs(yaw)), ...
    "acceleration_rms_mps2", rms(egoA,"omitnan"), ...
    "acceleration_abs_max_mps2", max(abs(egoA)), ...
    "jerk_rms_mps3", rms(diff(egoA)./dt,"omitnan"), ...
    "steering_rms_rad", rms(steer,"omitnan"), ...
    "steering_abs_max_rad", max(abs(steer)), ...
    "steering_rate_rms_radps", rms(diff(steer)./dt,"omitnan"), ...
    "collision_any", any(collision > 0.5), "all_finite", all(isfinite(allValues)));
end

function row = localEmptyScenario()
row = struct("id", "", "inputs", struct(), "requested_inputs", struct(), ...
    "stop_time_s", 0, "simulate_s", 0, "logs", struct(), ...
    "metrics", struct(), "required_logs_present", false(1,9), ...
    "scenario_application_pass", false, "simulation_pass", false, ...
    "required_evidence_pass", false, "valid", false);
end

function localClose(model)
if bdIsLoaded(model), close_system(model, 0); end
if bdIsLoaded("LFRefMdl"), close_system("LFRefMdl", 0); end
end

function binding = localFilePresence(pathValue)
assert(isfile(pathValue), "SimuVerity:FileMissing", "Required file is missing: %s", pathValue);
binding = "present";
end

function localWriteJson(pathValue, value)
fid = fopen(pathValue, "w", "n", "UTF-8");
assert(fid >= 0, "SimuVerity:XAUTO09:EvidenceWrite", "Cannot write evidence.");
cleanup = onCleanup(@() fclose(fid)); %#ok<NASGU>
fwrite(fid, jsonencode(value, PrettyPrint=true), "char");
end
